            StoryParagraph("Later, I was given a cell of my own, because they said I was dangerous.", "بعداً سلول خودم را به من دادند، چون گفتند خطرناکم."),
            StoryParagraph("The cell was small and dark; there was a bed, a table, and a bucket.", "سلول کوچک و تاریک بود؛ تختی بود، میزی و سطلی."),
            StoryParagraph("I did not mind the cell; I had never needed much space.", "سلول را بد نمی‌دیدم؛ هرگز به فضای زیادی نیاز نداشتم."),
            StoryParagraph("I thought about my apartment, about the sea, about Marie.", "به آپارتمانم فکر کردم، به دریا، به ماری."),
            StoryParagraph("At first, I did not realize that I was a prisoner.", "ابتدا نفهمیدم که زندانی‌ام."),
            StoryParagraph("The days were long and quiet, and I slept a lot.", "روزها طولانی و ساکت بودند و زیاد می‌خوابیدم."),
            StoryParagraph("The lawyer came to see me; he said he would defend me.", "وکیل به دیدنم آمد؛ گفت دفاعم می‌کند."),
            StoryParagraph("He asked me many questions about my life, about my mother, about my feelings.", "سوال‌های بسیاری درباره زندگی‌ام پرسید، درباره مادرم، درباره احساساتم."),
            StoryParagraph("I told him the truth, that I had not felt anything at my mother's funeral.", "حقیقت را به او گفتم، که در خاکسپاری مادرم چیزی حس نکرده‌ام."),
            StoryParagraph("He was shocked, and he said that this would hurt my case.", "شوکه شد و گفت این به پرونده‌ام آسیب می‌زند."),
            StoryParagraph("I said it was the truth, and that was all that mattered.", "گفتم حقیقت است و همین تنها چیزی است که اهمیت دارد."),
            StoryParagraph("Marie wrote to me, and she came to visit.", "ماری برایم نامه نوشت و به دیدارم آمد."),
            StoryParagraph("She said she still wanted to marry me.", "گفت هنوز می‌خواهد با من ازدواج کند."),
            StoryParagraph("I said that we could marry when I got out, if she still wanted.", "گفتم می‌توانیم وقتی بیرون آمدم ازدواج کنیم، اگر هنوز بخواهد."),
            StoryParagraph("I did not know if I loved her, but I did not want to hurt her.", "نمی‌دانستم دوستش دارم یا نه، اما نمی‌خواستم زخمی‌اش کنم."),
            StoryParagraph("The days passed, and the months passed, and I grew used to prison.", "روزها گذشتند و ماه‌ها و به زندان عادت کردم."),
            StoryParagraph("I learned to live without cigarettes, without wine, without women.", "یاد گرفتم بدون سیگار زندگی کنم، بدون شراب، بدون زنان."),
            StoryParagraph("I learned to remember my apartment in detail, piece by piece.", "یاد گرفتم آپارتمانم را با جزئیات به یاد بیاورم، تکه‌تکه."),
            StoryParagraph("I learned to hear the footsteps of the guards before they arrived.", "یاد گرفتم صدای قدم‌های نگهبانان را پیش از رسیدنشان بشنوم."),
            StoryParagraph("I learned that a man can live on very little, and still be alive.", "یاد گرفتم انسان می‌تواند با اندک زندگی کند و هنوز زنده باشد."),
            StoryParagraph("I began to think about my mother, about her life, about her death.", "شروع کردم به فکر کردن درباره مادرم، درباره زندگی‌اش، درباره مرگش."),
            StoryParagraph("I understood now that she had been happy in the home, with her friends, with her walks.", "حالا می‌فهمیدم که در خانه سالمندان خوشحال بوده، با دوستانش، با قدم‌هایش."),
            StoryParagraph("And I understood that I had loved her, in my own way.", "و می‌فهمیدم که دوستش داشته بودم، به شیوه خودم."),
            StoryParagraph("I began to feel that my life was not so different from hers.", "شروع کردم به حس کردن که زندگی‌ام از زندگی او چندان متفاوت نبود."),
            StoryParagraph("We are all in prison, I thought, of one kind or another.", "فکر کردم همه‌مان زندانی‌ایم، از نوعی یا دیگری."),
            StoryParagraph("Some prisons are made of stone, others of obligation, others of desire.", "برخی زندان‌ها از سنگ‌اند، برخی از وظیفه، برخی از میل."),
            StoryParagraph("But all prisons are the same, in the end, in that they keep us from being free.", "اما همه زندان‌ها در پایان یکی هستند، در اینکه ما را از آزاد بودن باز می‌دارند."),
            StoryParagraph("And freedom, I came to understand, is not something that can be given or taken away.", "و آزادی، شروع کردم به فهمیدن، چیزی نیست که بشود داد یا گرفت."),
            StoryParagraph("Freedom is a state of mind, a way of being, a choice that we make.", "آزادی حالتی ذهنی است، شیوه‌ای از بودن، انتخابی که می‌کنیم."),
            StoryParagraph("And even in prison, even in the darkest cell, we can choose to be free.", "و حتی در زندان، حتی در تاریک‌ترین سلول، می‌توانیم انتخاب کنیم آزاد باشیم."),
            StoryParagraph("The trial, I was told, would take place soon.", "به من گفته شد محاکمه به‌زودی برگزار می‌شود."),
            StoryParagraph("I did not worry about it; I did not worry about anything.", "نگرانش نبودم؛ نگران هیچ چیز نبودم."),
            StoryParagraph("I had become indifferent to my fate, indifferent to the outcome.", "نسبت به سرنوشتم بی‌تفاوت شده بودم، نسبت به نتیجه."),
            StoryParagraph("Whatever happened, happened; I would accept it, as I had accepted everything else.", "هر چه می‌شد، می‌شد؛ می‌پذیرفتم، همانطور که هر چیز دیگری را پذیرفته بودم."),
            StoryParagraph("I waited for the trial, for the verdict, for the sentence.", "منتظر محاکمه ماندم، منتظر حکم، منتظر مجازات."),
            StoryParagraph("And I waited without fear, without hope, without any feeling at all.", "و بی‌ترس منتظر ماندم، بی‌امید، بی‌هیچ احساسی."),
            StoryParagraph("I was alive, and that was enough; the rest did not matter.", "زنده بودم و همین کافی بود؛ باقی اهمیت نداشت."),
            StoryParagraph("Or so I told myself, in those days, in that prison, in that life.", "یا اینطور به خودم می‌گفتم، در آن روزها، در آن زندان، در آن زندگی.")
        )
    )

    // ─────────── فصل ۵: محاکمه ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Trial", titlePersian = "محاکمه",
        paragraphs = listOf(
            StoryParagraph("My trial began on a hot day in June.", "محاکمه‌ام در روزی گرم از ژوئن آغاز شد."),
            StoryParagraph("The courtroom was crowded with people; they had come to see the criminal.", "دادگاه پر از مردم بود؛ آمده بودند مجرم را ببینند."),
            StoryParagraph("The judge sat at the front, above everyone else, wearing black robes.", "قاضی در جلو نشسته بود، بالای همه، با جامه‌های سیاه."),
            StoryParagraph("The jury sat to the side, watching me with curiosity.", "هیئت منصفه کناری نشسته بود، با کنجکاوی تماشایم می‌کرد."),
            StoryParagraph("The prosecutor stood up and began to speak.", "دادستان برخاست و شروع به صحبت کرد."),
            StoryParagraph("He said I was a monster, a man without conscience, a danger to society.", "گفت هیولایم، مردی بدون وجدان، خطری برای جامعه."),
            StoryParagraph("He said I had killed an Arab with no reason, in cold blood.", "گفت عربی را بی‌دلیل کشته‌ام، در خونسردی."),
            StoryParagraph("He said I had shown no remorse, no grief, no humanity.", "گفت هیچ پشیمانی نشان نداده‌ام، نه اندوه، نه انسانیت."),
            StoryParagraph("He said I had not cried at my mother's funeral.", "گفت در خاکسپاری مادرم گریه نکرده‌ام."),
            StoryParagraph("He said I had gone to a funny movie the day after she died.", "گفت روز بعد از مرگش به فیلم خنده‌داری رفته‌ام."),
            StoryParagraph("He said I had started an affair with a woman the day after she died.", "گفت روز بعد از مرگش با زنی رابطه‌ای آغاز کرده‌ام."),
            StoryParagraph("He said this proved that I had no soul, that I was a stranger to humanity.", "گفت این ثابت می‌کند روحی ندارم، که بیگانه‌ام از بشریت."),
            StoryParagraph("My lawyer defended me as best he could.", "وکیلم تا جایی که می‌توانست دفاعم کرد."),
            StoryParagraph("He said I was a hard-working man, a good son, a good neighbor.", "گفت مردی زحمتکشم، پسر خوبی، همسایه خوبی."),
            StoryParagraph("He said the murder was a moment of madness, caused by the sun.", "گفت قتل لحظه‌ای از جنون بود، ناشی از خورشید."),
            StoryParagraph("But the jury did not believe him; they had already made up their minds.", "اما هیئت منصفه باورش نکرد؛ از قبل ذهنشان را ساخته بودند."),
            StoryParagraph("The judge asked me if I had anything to say.", "قاضی پرسید چیزی برای گفتن دارم."),
            StoryParagraph("I said that it was because of the sun.", "گفتم به خاطر خورشید بود."),
            StoryParagraph("The courtroom burst into laughter.", "دادگاه در خنده ترکید."),
            StoryParagraph("The judge said I did not understand the gravity of my crime.", "قاضی گفت جدی بودن جنایتم را نمی‌فهمم."),
            StoryParagraph("I said I understood very well; I just didn't see what difference it made.", "گفتم خیلی خوب می‌فهمم؛ فقط نمی‌بینم چه تفاوتی می‌کند."),
            StoryParagraph("I was asked about my mother, about my feelings, about my beliefs.", "درباره مادرم پرسیده شد، درباره احساساتم، درباره باورهایم."),
            StoryParagraph("I said I did not believe in God.", "گفتم به خدا باور ندارم."),
            StoryParagraph("The courtroom was shocked; the judge said this was scandalous.", "دادگاه شوکه شد؛ قاضی گفت این رسوایی است."),
            StoryParagraph("I said I had no opinion on the matter; it did not seem important to me.", "گفتم نظری ندارم؛ برایم مهم به نظر نمی‌رسد."),
            StoryParagraph("The prosecutor said I was a danger to society and should be executed.", "دادستان گفت برای جامعه خطرم و باید اعدام شوم."),
            StoryParagraph("My lawyer begged for mercy; he said I was a good man who had made a mistake.", "وکیلم التماس رحم کرد؛ گفت مرد خوبی‌ام که اشتباهی کرده."),
            StoryParagraph("The jury left to deliberate; they were gone for less than an hour.", "هیئت منصفه برای مشورت رفت؛ کمتر از یک ساعت غایب بودند."),
            StoryParagraph("When they returned, they pronounced me guilty.", "وقتی برگشتند، مجرم اعلامم کردند."),
            StoryParagraph("The judge sentenced me to death by guillotine in the public square.", "قاضی به مرگ با گیوتین در میدان عمومی محکومم کرد."),
            StoryParagraph("I listened to the sentence without emotion.", "حکم را بدون احساس شنیدم."),
            StoryParagraph("The verdict, I realized, was based not on my crime but on who I was.", "دریافتم که حکم نه بر اساس جنایتم بلکه بر اساس آنکه بودم صادر شده."),
            StoryParagraph("They condemned me not for killing a man but for not loving my mother.", "نه برای کشتن مردی محکومم کردند بلکه برای دوست نداشتن مادرم."),
            StoryParagraph("They condemned me not for what I had done but for what I was.", "نه برای آنچه کرده بودم محکومم کردند بلکه برای آنچه بودم."),
            StoryParagraph("They condemned me because I did not fit into their world, their morality, their expectations.", "محکومم کردند چون در دنیایشان جا نمی‌شدم، در اخلاقشان، در انتظاراتشان."),
            StoryParagraph("And for that, I realized, there was no defense.", "و برای آن، دریافتم، دفاعی نبود."),
            StoryParagraph("I was a stranger in their world, an outsider, an alien.", "بیگانه بودم در دنیایشان، بیرونی، بیگانه."),
            StoryParagraph("And strangers, I understood, are always condemned.", "و بیگانگان، فهمیدم، همیشه محکوم می‌شوند."),
            StoryParagraph("The trial was over; the sentence had been passed; the story was ending.", "محاکمه تمام شده بود؛ حکم صادر شده بود؛ داستان پایان می‌یافت."),
            StoryParagraph("And yet, I felt strangely calm.", "و با این حال، به شکلی عجیب آرام بودم."),
            StoryParagraph("I had accepted my fate, as I had accepted everything else.", "سرنوشتم را پذیرفته بودم، همانطور که هر چیز دیگری را پذیرفته بودم."),
            StoryParagraph("And in that acceptance, in that surrender, there was a kind of freedom.", "و در آن پذیرش، در آن تسلیم، نوعی آزادی بود.")
        )
    )

    // ─────────── فصل ۶: بیگانه ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Stranger", titlePersian = "بیگانه",
        paragraphs = listOf(
            StoryParagraph("In my cell, on the night before my execution, I waited for the morning.", "در سلولم، شب پیش از اعدامم، منتظر صبح ماندم."),
            StoryParagraph("A priest came to visit me; he wanted me to turn to God.", "کشیشی به دیدارم آمد؛ می‌خواست به خدا رو آورم."),
            StoryParagraph("He asked me if I believed in God, and I said no.", "پرسید آیا به خدا باور دارم و گفتم نه."),
            StoryParagraph("He said that even the most hardened criminal could repent.", "گفت حتی سرسخت‌ترین جنایتکار هم می‌تواند توبه کند."),
            StoryParagraph("I said I had nothing to repent for, that I did not regret what I had done.", "گفتم چیزی برای توبه ندارم، از آنچه کرده‌ام پشیمان نیستم."),
            StoryParagraph("The priest asked me why I had killed the Arab.", "کشیش پرسید چرا عرب را کشتم."),
            StoryParagraph("I said it was because of the sun.", "گفتم به خاطر خورشید بود."),
            StoryParagraph("He did not understand, and he kept insisting, and I began to feel angry.", "نفهمید و اصرار کرد و شروع کردم به حس خشم."),
            StoryParagraph("I shouted at him, and I told him I had no time for his God, for his hopes, for his promises.", "بر سرش فریاد زدم و گفتم وقتی برای خدایش ندارم، برای امیدهایش، برای وعده‌هایش."),
            StoryParagraph("I told him that my whole life had been determined by small things.", "گفتم تمام زندگی‌ام توسط چیزهای کوچک تعیین شده."),
            StoryParagraph("The sun, the heat, the sand, the sea; none of it mattered, and yet all of it mattered.", "خورشید، گرما، ماسه، دریا؛ هیچ‌کدام مهم نبود و با این حال همه مهم بود."),
            StoryParagraph("The priest left, and I was alone with my thoughts.", "کشیش رفت و من با افکارم تنها شدم."),
            StoryParagraph("I thought about my mother, about Marie, about Raymond, about the Arab.", "به مادرم فکر کردم، به ماری، به ریموند، به عرب."),
            StoryParagraph("I thought about my life, about all the things I had done and not done.", "به زندگی‌ام فکر کردم، به همه چیزهایی که کرده بودم و نکرده بودم."),
            StoryParagraph("And I understood, at last, that none of it mattered.", "و سرانجام فهمیدم که هیچ‌کدام مهم نیست."),
            StoryParagraph("Life is absurd; there is no meaning, no purpose, no reason.", "زندگی پوچ است؛ معنایی نیست، هدفی نیست، دلیلی نیست."),
            StoryParagraph("We are born, we live, we die, and nothing we do makes any difference.", "زاده می‌شویم، زندگی می‌کنیم، می‌میریم و هیچ کاری که می‌کنیم تفاوتی ایجاد نمی‌کند."),
            StoryParagraph("And yet, in that absurdity, in that meaninglessness, there is a strange freedom.", "و با این حال، در آن پوچی، در آن بی‌معنایی، آزادی‌ای عجیب هست."),
            StoryParagraph("Because if nothing matters, then we are free to do whatever we want.", "زیرا اگر هیچ چیز مهم نیست، آزادیم هر کاری بخواهیم بکنیم."),
            StoryParagraph("We are free to live as we choose, to die as we choose, to be as we choose.", "آزادیم آنطور که می‌خواهیم زندگی کنیم، آنطور که می‌خواهیم بمیریم، آنطور که می‌خواهیم باشیم."),
            StoryParagraph("And that freedom, that terrible freedom, is the only thing that matters.", "و آن آزادی، آن آزادی هولناک، تنها چیزی است که اهمیت دارد."),
            StoryParagraph("I had lived my life without illusions, without false hopes, without belief in things that did not exist.", "زندگی‌ام را بدون توهم زندگی کرده بودم، بدون امیدهای دروغین، بدون باور به چیزهایی که وجود نداشتند."),
            StoryParagraph("And now, facing death, I did not regret it.", "و حالا، در رویارویی با مرگ، پشیمان نبودم."),
            StoryParagraph("I had been happy, and I was still happy, in my own way.", "خوشحال بوده بودم و هنوز خوشحال بودم، به شیوه خودم."),
            StoryParagraph("I had loved the sun, the sea, the sand; I had loved Marie, in my own way.", "خورشید را دوست داشته بودم، دریا را، ماسه را؛ ماری را دوست داشته بودم، به شیوه خودم."),
            StoryParagraph("I had lived, truly lived, without pretense, without lies, without self-deception.", "زیسته بودم، به‌راستی زیسته بودم، بدون تظاهر، بدون دروغ، بدون خودفریبی."),
            StoryParagraph("And in the end, that was enough.", "و در پایان، همین کافی بود."),
            StoryParagraph("The morning came, and the guards came for me, and I went to my death without fear.", "صبح آمد و نگهبانان به دنبالم آمدند و بدون ترس به سمت مرگم رفتم."),
            StoryParagraph("I looked at the sky one last time, and I saw that it was blue and beautiful.", "یک بار آخر به آسمان نگاه کردم و دیدم آبی و زیباست."),
            StoryParagraph("I thought about my mother, and I understood her at last, at the very end.", "به مادرم فکر کردم و سرانجام فهمیدمش، در همان پایان."),
            StoryParagraph("I opened myself to the tender indifference of the world.", "خودم را بر بی‌تفاوتی لطیف جهان گشودم."),
            StoryParagraph("And I found it so much like myself, so much like a brother, that I understood I had been happy, and that I was still happy.", "و آنقدر شبیه خودم یافتمش، آنقدر شبیه برادری، که فهمیدم خوشحال بوده بودم و هنوز خوشحالم."),
            StoryParagraph("For the first time, in the face of the hostile universe, I opened myself to it.", "برای نخستین بار، در رویارویی با جهان خصمانه، خودم را بر آن گشودم."),
            StoryParagraph("And I hoped that there would be many spectators at my execution, and that they would greet me with cries of hate.", "و امیدوار بودم تماشاگران بسیاری در اعدامم باشند و با فریادهای نفرت پذیرایم شوند."),
            StoryParagraph("For that, I understood, would be the only way to prove that I was not alone.", "زیرا این، فهمیدم، تنها راه اثبات اینکه تنها نیستم می‌بود."),
            StoryParagraph("I was not alone; I was one with the universe, with its beauty and its cruelty, with its sunlight and its darkness.", "تنها نبودم؛ با جهان یکی بودم، با زیبایی و بی‌رحمی‌اش، با روشنایی و تاریکی‌اش."),
            StoryParagraph("And so the stranger, the outsider, the alien, found peace at last.", "و اینگونه بیگانه، بیرونی، بیگانه، سرانجام آرامش یافت."),
            StoryParagraph("Not the peace of God, not the peace of salvation, but the peace of acceptance.", "نه آرامش خدا، نه آرامش رستگاری، بلکه آرامش پذیرش."),
            StoryParagraph("The peace of knowing that nothing matters, and being free to live without fear.", "آرامش دانستن اینکه هیچ چیز مهم نیست و آزاد بودن به زندگی بدون ترس."),
            StoryParagraph("The peace of the absurd, which is the only peace available to us in this world.", "آرامش پوچی، که تنها آرامش موجود برای ما در این جهان است."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the absurd man, every ending is also a beginning.", "زیرا برای مرد پوچ، هر پایانی آغازی هم هست.")
        )
    )
}